import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const STEPS = ['Voucher', 'Personal', 'Guardian', 'Programmes', 'Academic', 'Employment', 'Documents'];

const PROGRAMMES = [
  { id: 'bsc-ph-disease-topup',   label: 'BSc Public Health (Disease Control Option) — Top-Up' },
  { id: 'bsc-ph-nutrition-topup', label: 'BSc Public Health (Nutrition Option) — Top-Up' },
  { id: 'bsc-nursing-access',     label: 'BSc Nursing (Access Programme)' },
  { id: 'mature-access-topup',    label: 'Mature Access Program (Top-Up)' },
];

const CORE_SUBJECTS = ['English Language', 'Core Mathematics', 'Integrated Science', 'Social Studies'];
const GRADES = ['A1', 'B2', 'B3', 'C4', 'C5', 'C6', 'D7', 'E8', 'F9'];

type ProgrammeChoice = { id: string; preference: string };
type SubjectGrade    = { subject: string; dateTaken: string; grade: string };
type Institution     = { name: string; from: string; to: string; certificate: string };
type Employment      = { employer: string; position: string; from: string; to: string };

const emptySubject     = (subject = ''): SubjectGrade => ({ subject, dateTaken: '', grade: '' });
const emptyInstitution = (): Institution => ({ name: '', from: '', to: '', certificate: '' });
const emptyEmployment  = (): Employment  => ({ employer: '', position: '', from: '', to: '' });

const ApplicationFormTopUp: React.FC = () => {
  const [step, setStep] = useState(1);

  const [voucherCode, setVoucherCode] = useState('');

  const [personal, setPersonal] = useState({
    title: '', surname: '', firstName: '', otherNames: '',
    gender: '', dob: '', nationality: 'Ghanaian', hometown: '',
    postalAddress: '', email: '', phone: '', physicalChallenge: '',
  });

  const [guardian, setGuardian] = useState({
    name: '', relationship: '', occupation: '',
    postalAddress: '', email: '', phone: '',
  });

  const [programmeChoices, setProgrammeChoices] = useState<ProgrammeChoice[]>([]);
  const [enrollmentOption, setEnrollmentOption] = useState('');
  const [financing, setFinancing] = useState<string[]>([]);
  const [otherFinancing, setOtherFinancing] = useState('');

  const [institutions, setInstitutions] = useState<Institution[]>([
    emptyInstitution(), emptyInstitution(), emptyInstitution(), emptyInstitution(),
  ]);

  // Top-up applicants always have diploma/HND — show diploma section by default
  // but also allow WASSCE entry if they have it
  const [hasWassce, setHasWassce] = useState(false);
  const [coreGrades, setCoreGrades] = useState<SubjectGrade[]>(CORE_SUBJECTS.map(emptySubject));
  const [electiveGrades, setElectiveGrades] = useState<SubjectGrade[]>([emptySubject(), emptySubject(), emptySubject()]);
  const [diplomaQuals, setDiplomaQuals] = useState([
    { qualification: '', subject: '', dateObtained: '', grade: '' },
    { qualification: '', subject: '', dateObtained: '', grade: '' },
  ]);

  const [employments, setEmployments] = useState<Employment[]>([
    emptyEmployment(), emptyEmployment(),
  ]);
  const [totalYearsWorked, setTotalYearsWorked] = useState('');

  const [files, setFiles] = useState<{ [k: string]: File | null }>({
    photo: null, certificates: null, transcripts: null, birthCert: null,
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });

  /* ── helpers ── */
  const hp = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) =>
    setPersonal(p => ({ ...p, [e.target.name]: e.target.value }));

  const hg = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) =>
    setGuardian(g => ({ ...g, [e.target.name]: e.target.value }));

  const toggleProgramme = (id: string) => {
    const exists = programmeChoices.find(p => p.id === id);
    if (exists) {
      setProgrammeChoices(prev => prev.filter(p => p.id !== id));
    } else if (programmeChoices.length < 3) {
      setProgrammeChoices(prev => [...prev, { id, preference: `${prev.length + 1}` }]);
    }
  };

  const preferenceLabel = (id: string) => {
    const found = programmeChoices.find(p => p.id === id);
    if (!found) return null;
    return ['1st', '2nd', '3rd'][parseInt(found.preference) - 1] || found.preference;
  };

  const toggleFinancing = (val: string) =>
    setFinancing(prev => prev.includes(val) ? prev.filter(f => f !== val) : [...prev, val]);

  const updateCoreGrade = (i: number, field: keyof SubjectGrade, val: string) =>
    setCoreGrades(prev => prev.map((g, idx) => idx === i ? { ...g, [field]: val } : g));

  const updateElectiveGrade = (i: number, field: keyof SubjectGrade, val: string) =>
    setElectiveGrades(prev => prev.map((g, idx) => idx === i ? { ...g, [field]: val } : g));

  const updateInstitution = (i: number, field: keyof Institution, val: string) =>
    setInstitutions(prev => prev.map((inst, idx) => idx === i ? { ...inst, [field]: val } : inst));

  const updateDiplomaQual = (i: number, field: string, val: string) =>
    setDiplomaQuals(prev => prev.map((q, idx) => idx === i ? { ...q, [field]: val } : q));

  const updateEmployment = (i: number, field: keyof Employment, val: string) =>
    setEmployments(prev => prev.map((e, idx) => idx === i ? { ...e, [field]: val } : e));

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.[0]) setFiles(f => ({ ...f, [e.target.name]: e.target.files![0] }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage({ type: '', text: '' });
    try {
      await new Promise(r => setTimeout(r, 2000));
      const appId = `TUP${Date.now().toString().slice(-6)}`;
      setMessage({
        type: 'success',
        text: `Top-Up application submitted successfully! Your Application ID is ${appId}. A confirmation has been sent to ${personal.email}.`,
      });
      setTimeout(() => (window.location.href = '/application-status'), 4000);
    } catch {
      setMessage({ type: 'error', text: 'Submission failed. Please try again.' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <header className="header">
        <div className="header-content">
          <div className="logo-section">
            <img src="http://wuc.edu.gh/wp-content/uploads/2025/05/WC-logo-on-white-1.jpg" alt="WUC Logo" />
            <div>
              <h1>Withrow University College</h1>
              <span className="logo-sub">Agona-Asamangah · Admission Portal</span>
            </div>
          </div>
          <nav>
            <ul className="nav-links">
              <li><Link to="/">Home</Link></li>
              <li><Link to="/purchase-voucher">Buy Voucher</Link></li>
              <li><Link to="/application-status">Check Status</Link></li>
            </ul>
          </nav>
        </div>
      </header>

      <div className="page-hero">
        <div className="page-hero-inner">
          <div style={{
            display: 'inline-block', background: 'rgba(201,168,76,0.25)',
            border: '1px solid rgba(201,168,76,0.5)', borderRadius: '999px',
            padding: '0.2rem 0.875rem', fontSize: '0.7rem', fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase' as const,
            color: 'var(--accent)', marginBottom: '0.625rem',
          }}>
            Top-Up / Access Programme
          </div>
          <h2>Undergraduate Admission — Top-Up Application</h2>
          <p>For applicants holding a Certificate, Diploma, HND or equivalent qualification. Write in block letters.</p>
        </div>
      </div>

      <div className="container-sm">
        {message.text && (
          <div className={`alert alert-${message.type === 'success' ? 'success' : 'error'}`}>{message.text}</div>
        )}

        {/* Step bar */}
        <div className="step-bar">
          {STEPS.map((label, i) => {
            const num = i + 1;
            const state = step > num ? 'done' : step === num ? 'active' : '';
            return (
              <div key={label} className={`step-item ${state}`}>
                <div className="step-dot">{step > num ? '✓' : num}</div>
                <div className="step-label">{label}</div>
              </div>
            );
          })}
        </div>

        <div className="card">

          {/* ── STEP 1: Voucher ── */}
          {step === 1 && (
            <div>
              <h3 className="section-title">Voucher Verification</h3>
              <p className="section-subtitle">Enter the voucher code received after payment to unlock the application form.</p>
              <div className="alert alert-info">
                This form is for <strong>Top-Up / Access Programme</strong> applicants who already hold a Certificate, Diploma, HND, or equivalent qualification.
                If you are a fresh WASSCE candidate, use the <Link to="/apply">Regular Application Form</Link>.
              </div>
              <div className="form-group">
                <label>Voucher Code *</label>
                <input
                  type="text"
                  value={voucherCode}
                  onChange={e => setVoucherCode(e.target.value.toUpperCase())}
                  placeholder="e.g. WUC12345678"
                  required
                  style={{ fontFamily: 'monospace', letterSpacing: '0.08em', fontSize: '1.05rem' }}
                />
              </div>
              <button type="button" onClick={() => voucherCode.trim() && setStep(2)} className="btn btn-primary">
                Continue →
              </button>
            </div>
          )}

          {/* ── STEP 2: Personal Particulars ── */}
          {step === 2 && (
            <div>
              <h3 className="section-title">Personal Particulars of Applicant</h3>

              {/* Passport photo placeholder */}
              <div style={{
                float: 'right', width: '110px', height: '130px',
                border: '2px dashed var(--border)', borderRadius: 'var(--radius-sm)',
                display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                background: 'var(--surface-3)', marginLeft: '1rem', marginBottom: '1rem',
                fontSize: '0.7rem', color: 'var(--text-muted)', textAlign: 'center' as const, padding: '0.5rem',
              }}>
                <span style={{ fontSize: '1.5rem', marginBottom: '0.25rem' }}>📷</span>
                Affix Passport Size Photo Here
              </div>

              <div className="form-grid">
                <div className="form-group">
                  <label>Title *</label>
                  <select name="title" value={personal.title} onChange={hp} required>
                    <option value="">Select</option>
                    <option>Mr</option><option>Mrs</option><option>Miss</option><option>Dr</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Surname *</label>
                  <input type="text" name="surname" value={personal.surname} onChange={hp} required style={{ textTransform: 'uppercase' }} />
                </div>
                <div className="form-group">
                  <label>First Name *</label>
                  <input type="text" name="firstName" value={personal.firstName} onChange={hp} required style={{ textTransform: 'uppercase' }} />
                </div>
                <div className="form-group">
                  <label>Other Name(s)</label>
                  <input type="text" name="otherNames" value={personal.otherNames} onChange={hp} style={{ textTransform: 'uppercase' }} />
                </div>
                <div className="form-group">
                  <label>Gender *</label>
                  <select name="gender" value={personal.gender} onChange={hp} required>
                    <option value="">Select</option>
                    <option>Male</option><option>Female</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Date of Birth *</label>
                  <input type="date" name="dob" value={personal.dob} onChange={hp} required />
                </div>
                <div className="form-group">
                  <label>Nationality *</label>
                  <input type="text" name="nationality" value={personal.nationality} onChange={hp} required />
                </div>
                <div className="form-group">
                  <label>Home Town *</label>
                  <input type="text" name="hometown" value={personal.hometown} onChange={hp} required />
                </div>
                <div className="form-group">
                  <label>Email Address *</label>
                  <input type="email" name="email" value={personal.email} onChange={hp} required />
                </div>
                <div className="form-group">
                  <label>Mobile Number *</label>
                  <input type="tel" name="phone" value={personal.phone} onChange={hp} placeholder="+233 XX XXX XXXX" required />
                </div>
              </div>
              <div className="form-group">
                <label>Permanent Postal Address *</label>
                <textarea name="postalAddress" value={personal.postalAddress} onChange={hp} rows={2} required style={{ textTransform: 'uppercase' }} />
              </div>
              <div className="form-group">
                <label>State Any Physical Challenge (if applicable)</label>
                <input type="text" name="physicalChallenge" value={personal.physicalChallenge} onChange={hp} placeholder="None / describe if applicable" />
              </div>

              <div style={{ display: 'flex', gap: '0.75rem' }}>
                <button type="button" onClick={() => setStep(1)} className="btn btn-ghost">← Back</button>
                <button type="button" onClick={() => setStep(3)} className="btn btn-primary">Continue →</button>
              </div>
            </div>
          )}

          {/* ── STEP 3: Guardian ── */}
          {step === 3 && (
            <div>
              <h3 className="section-title">Particulars of Parent / Guardian</h3>
              <div className="form-group">
                <label>Full Name *</label>
                <input type="text" name="name" value={guardian.name} onChange={hg} required style={{ textTransform: 'uppercase' }} />
              </div>
              <div className="form-grid">
                <div className="form-group">
                  <label>Relationship *</label>
                  <select name="relationship" value={guardian.relationship} onChange={hg} required>
                    <option value="">Select</option>
                    <option>Father</option><option>Mother</option><option>Guardian</option>
                    <option>Sibling</option><option>Spouse</option><option>Other</option>
                  </select>
                </div>
                <div className="form-group">
                  <label>Occupation *</label>
                  <input type="text" name="occupation" value={guardian.occupation} onChange={hg} required />
                </div>
                <div className="form-group">
                  <label>Email Address</label>
                  <input type="email" name="email" value={guardian.email} onChange={hg} />
                </div>
                <div className="form-group">
                  <label>Mobile Number *</label>
                  <input type="tel" name="phone" value={guardian.phone} onChange={hg} required />
                </div>
              </div>
              <div className="form-group">
                <label>Permanent Postal Address *</label>
                <textarea name="postalAddress" value={guardian.postalAddress} onChange={hg} rows={2} required style={{ textTransform: 'uppercase' }} />
              </div>
              <div style={{ display: 'flex', gap: '0.75rem' }}>
                <button type="button" onClick={() => setStep(2)} className="btn btn-ghost">← Back</button>
                <button type="button" onClick={() => setStep(4)} className="btn btn-primary">Continue →</button>
              </div>
            </div>
          )}

          {/* ── STEP 4: Programmes & Enrollment ── */}
          {step === 4 && (
            <div>
              <h3 className="section-title">Programme Selection</h3>
              <p className="section-subtitle">
                Tick your preferred programmes and indicate order of preference (1st, 2nd, 3rd). Maximum 3 selections.
              </p>

              <div className="table-wrap" style={{ marginBottom: '1.5rem' }}>
                <table className="data-table">
                  <thead>
                    <tr>
                      <th style={{ width: '40px' }}>No.</th>
                      <th>Programme</th>
                      <th style={{ width: '80px', textAlign: 'center' }}>Select (✓)</th>
                      <th style={{ width: '120px', textAlign: 'center' }}>Preference</th>
                    </tr>
                  </thead>
                  <tbody>
                    {PROGRAMMES.map((prog, i) => {
                      const selected = !!programmeChoices.find(p => p.id === prog.id);
                      const pref = preferenceLabel(prog.id);
                      return (
                        <tr key={prog.id} style={{ background: selected ? 'var(--info-bg)' : undefined }}>
                          <td style={{ color: 'var(--text-muted)', fontWeight: 600 }}>{i + 1}.</td>
                          <td style={{ fontWeight: selected ? 600 : 400 }}>{prog.label}</td>
                          <td style={{ textAlign: 'center' }}>
                            <input
                              type="checkbox"
                              checked={selected}
                              onChange={() => toggleProgramme(prog.id)}
                              disabled={!selected && programmeChoices.length >= 3}
                              style={{ width: '18px', height: '18px', cursor: 'pointer', accentColor: 'var(--primary-mid)' }}
                            />
                          </td>
                          <td style={{ textAlign: 'center' }}>
                            {pref && <span className="badge badge-info">{pref} Choice</span>}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>

              {programmeChoices.length === 0 && (
                <div className="alert alert-warning" style={{ marginBottom: '1.5rem' }}>
                  Please select at least one programme to continue.
                </div>
              )}

              <hr className="divider" />
              <h4 style={{ fontSize: '0.875rem', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '1rem', letterSpacing: '0.02em' }}>
                Enrollment Option *
              </h4>
              <div style={{ display: 'flex', gap: '1.5rem', flexWrap: 'wrap', marginBottom: '1.5rem' }}>
                {['Regular', 'Weekend', 'Sandwich'].map(opt => (
                  <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', fontSize: '0.9rem', fontWeight: 500 }}>
                    <input type="radio" name="enrollment" value={opt} checked={enrollmentOption === opt}
                      onChange={() => setEnrollmentOption(opt)}
                      style={{ width: '16px', height: '16px', accentColor: 'var(--primary-mid)' }} />
                    {opt}
                  </label>
                ))}
              </div>

              <hr className="divider" />
              <h4 style={{ fontSize: '0.875rem', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '1rem', letterSpacing: '0.02em' }}>
                Financing of Education *
              </h4>
              <div style={{ display: 'flex', gap: '1.25rem', flexWrap: 'wrap', marginBottom: '0.5rem' }}>
                {['SSNIT Students Loan Scheme', 'Employer', 'Guardian', 'Self'].map(opt => (
                  <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', cursor: 'pointer', fontSize: '0.875rem', fontWeight: 500 }}>
                    <input type="checkbox" checked={financing.includes(opt)} onChange={() => toggleFinancing(opt)}
                      style={{ width: '16px', height: '16px', accentColor: 'var(--primary-mid)' }} />
                    {opt}
                  </label>
                ))}
              </div>
              <div className="form-group" style={{ marginTop: '0.75rem' }}>
                <label>Other (specify)</label>
                <input type="text" value={otherFinancing} onChange={e => setOtherFinancing(e.target.value)} placeholder="Describe other financing source" />
              </div>

              <div style={{ display: 'flex', gap: '0.75rem', marginTop: '0.5rem' }}>
                <button type="button" onClick={() => setStep(3)} className="btn btn-ghost">← Back</button>
                <button type="button"
                  onClick={() => programmeChoices.length > 0 && enrollmentOption && setStep(5)}
                  className="btn btn-primary"
                  disabled={programmeChoices.length === 0 || !enrollmentOption}>
                  Continue →
                </button>
              </div>
            </div>
          )}

          {/* ── STEP 5: Institutions & Academic Performance ── */}
          {step === 5 && (
            <div>
              <h3 className="section-title">Institutions Attended / Qualifications</h3>
              <div className="table-wrap" style={{ marginBottom: '1rem' }}>
                <table className="data-table">
                  <thead>
                    <tr>
                      <th style={{ width: '36px' }}>No.</th>
                      <th>Name of Institution</th>
                      <th style={{ width: '100px' }}>From</th>
                      <th style={{ width: '100px' }}>To</th>
                      <th style={{ width: '170px' }}>Certificate Awarded</th>
                    </tr>
                  </thead>
                  <tbody>
                    {institutions.map((inst, i) => (
                      <tr key={i}>
                        <td style={{ color: 'var(--text-muted)', fontWeight: 600 }}>{i + 1}</td>
                        <td><input type="text" value={inst.name} onChange={e => updateInstitution(i, 'name', e.target.value)}
                          placeholder="School / College / University"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="number" value={inst.from} onChange={e => updateInstitution(i, 'from', e.target.value)}
                          placeholder="YYYY" min="1980" max="2026"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="number" value={inst.to} onChange={e => updateInstitution(i, 'to', e.target.value)}
                          placeholder="YYYY" min="1980" max="2026"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="text" value={inst.certificate} onChange={e => updateInstitution(i, 'certificate', e.target.value)}
                          placeholder="e.g. HND, Diploma"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <button type="button" onClick={() => setInstitutions(p => [...p, emptyInstitution()])}
                className="btn btn-ghost btn-sm" style={{ marginBottom: '1.5rem' }}>
                + Add Institution
              </button>

              <hr className="divider" />

              {/* Diploma / HND section — always shown for top-up */}
              <h4 style={{ fontSize: '0.875rem', fontWeight: 700, color: 'var(--text-secondary)', marginBottom: '0.5rem' }}>
                Diploma / HND / Nursing / Teaching Qualification *
              </h4>
              <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '1rem' }}>
                Enter all tertiary qualifications (DBS, HND, Nursing Diploma, Teaching Diploma, Nursing Certificate, Teaching Certificate, etc.)
              </p>
              <div className="table-wrap" style={{ marginBottom: '1rem' }}>
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Qualification</th>
                      <th>Subject / Programme Studied</th>
                      <th style={{ width: '130px' }}>Date Obtained</th>
                      <th style={{ width: '90px' }}>Grade / Class</th>
                    </tr>
                  </thead>
                  <tbody>
                    {diplomaQuals.map((q, i) => (
                      <tr key={i}>
                        <td><input type="text" value={q.qualification} onChange={e => updateDiplomaQual(i, 'qualification', e.target.value)}
                          placeholder="e.g. HND, Nursing Diploma"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="text" value={q.subject} onChange={e => updateDiplomaQual(i, 'subject', e.target.value)}
                          placeholder="e.g. General Nursing"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="month" value={q.dateObtained} onChange={e => updateDiplomaQual(i, 'dateObtained', e.target.value)}
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="text" value={q.grade} onChange={e => updateDiplomaQual(i, 'grade', e.target.value)}
                          placeholder="e.g. Merit"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <button type="button" onClick={() => setDiplomaQuals(p => [...p, { qualification: '', subject: '', dateObtained: '', grade: '' }])}
                className="btn btn-ghost btn-sm" style={{ marginBottom: '1.5rem' }}>
                + Add Qualification
              </button>

              <hr className="divider" />

              {/* Optional WASSCE toggle */}
              <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1rem' }}>
                <input type="checkbox" id="hasWassce" checked={hasWassce} onChange={e => setHasWassce(e.target.checked)}
                  style={{ width: '16px', height: '16px', accentColor: 'var(--primary-mid)', cursor: 'pointer' }} />
                <label htmlFor="hasWassce" style={{ fontSize: '0.875rem', fontWeight: 600, cursor: 'pointer', color: 'var(--text-secondary)' }}>
                  I also have WASSCE / SSCE results to declare
                </label>
              </div>

              {hasWassce && (
                <div>
                  <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '0.75rem', fontWeight: 600, textTransform: 'uppercase' as const, letterSpacing: '0.04em' }}>
                    Core Subjects
                  </p>
                  <div className="table-wrap" style={{ marginBottom: '1.25rem' }}>
                    <table className="data-table">
                      <thead>
                        <tr><th>Subject</th><th style={{ width: '140px' }}>Date Taken</th><th style={{ width: '100px' }}>Grade</th></tr>
                      </thead>
                      <tbody>
                        {coreGrades.map((row, i) => (
                          <tr key={i}>
                            <td style={{ fontWeight: 500 }}>{row.subject}</td>
                            <td><input type="month" value={row.dateTaken} onChange={e => updateCoreGrade(i, 'dateTaken', e.target.value)}
                              style={{ border: 'none', outline: 'none', background: 'transparent', fontSize: '0.875rem', width: '100%' }} /></td>
                            <td>
                              <select value={row.grade} onChange={e => updateCoreGrade(i, 'grade', e.target.value)}
                                style={{ border: 'none', outline: 'none', background: 'transparent', fontSize: '0.875rem', width: '100%' }}>
                                <option value="">—</option>
                                {GRADES.map(g => <option key={g}>{g}</option>)}
                              </select>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '0.75rem', fontWeight: 600, textTransform: 'uppercase' as const, letterSpacing: '0.04em' }}>
                    Elective Subjects
                  </p>
                  <div className="table-wrap" style={{ marginBottom: '0.75rem' }}>
                    <table className="data-table">
                      <thead>
                        <tr><th>Subject</th><th style={{ width: '140px' }}>Date Taken</th><th style={{ width: '100px' }}>Grade</th></tr>
                      </thead>
                      <tbody>
                        {electiveGrades.map((row, i) => (
                          <tr key={i}>
                            <td><input type="text" value={row.subject} onChange={e => updateElectiveGrade(i, 'subject', e.target.value)}
                              placeholder={`Elective ${i + 1}`}
                              style={{ border: 'none', outline: 'none', background: 'transparent', fontSize: '0.875rem', width: '100%' }} /></td>
                            <td><input type="month" value={row.dateTaken} onChange={e => updateElectiveGrade(i, 'dateTaken', e.target.value)}
                              style={{ border: 'none', outline: 'none', background: 'transparent', fontSize: '0.875rem', width: '100%' }} /></td>
                            <td>
                              <select value={row.grade} onChange={e => updateElectiveGrade(i, 'grade', e.target.value)}
                                style={{ border: 'none', outline: 'none', background: 'transparent', fontSize: '0.875rem', width: '100%' }}>
                                <option value="">—</option>
                                {GRADES.map(g => <option key={g}>{g}</option>)}
                              </select>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <button type="button" onClick={() => setElectiveGrades(p => [...p, emptySubject()])}
                    className="btn btn-ghost btn-sm" style={{ marginBottom: '1rem' }}>
                    + Add Elective Subject
                  </button>
                </div>
              )}

              <div style={{ display: 'flex', gap: '0.75rem', marginTop: '1rem' }}>
                <button type="button" onClick={() => setStep(4)} className="btn btn-ghost">← Back</button>
                <button type="button" onClick={() => setStep(6)} className="btn btn-primary">Continue →</button>
              </div>
            </div>
          )}

          {/* ── STEP 6: Employment History ── */}
          {step === 6 && (
            <div>
              <h3 className="section-title">Employment History</h3>
              <p className="section-subtitle">Complete if applicable. Leave blank if not employed.</p>

              <div className="table-wrap" style={{ marginBottom: '1rem' }}>
                <table className="data-table">
                  <thead>
                    <tr>
                      <th style={{ width: '36px' }}>No.</th>
                      <th>Employer / Organisation</th>
                      <th style={{ width: '160px' }}>Position Held</th>
                      <th style={{ width: '110px' }}>From</th>
                      <th style={{ width: '110px' }}>To</th>
                    </tr>
                  </thead>
                  <tbody>
                    {employments.map((emp, i) => (
                      <tr key={i}>
                        <td style={{ color: 'var(--text-muted)', fontWeight: 600 }}>{i + 1}.</td>
                        <td><input type="text" value={emp.employer} onChange={e => updateEmployment(i, 'employer', e.target.value)}
                          placeholder="Organisation name"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="text" value={emp.position} onChange={e => updateEmployment(i, 'position', e.target.value)}
                          placeholder="Job title"
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="month" value={emp.from} onChange={e => updateEmployment(i, 'from', e.target.value)}
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                        <td><input type="month" value={emp.to} onChange={e => updateEmployment(i, 'to', e.target.value)}
                          style={{ border: 'none', outline: 'none', width: '100%', background: 'transparent', fontSize: '0.875rem' }} /></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <button type="button" onClick={() => setEmployments(p => [...p, emptyEmployment()])}
                className="btn btn-ghost btn-sm" style={{ marginBottom: '1.5rem' }}>
                + Add Employment
              </button>

              <div className="form-group" style={{ maxWidth: '240px' }}>
                <label>Total Number of Years Worked</label>
                <input type="number" value={totalYearsWorked} onChange={e => setTotalYearsWorked(e.target.value)}
                  placeholder="e.g. 5" min="0" max="50" />
              </div>

              <div style={{ display: 'flex', gap: '0.75rem', marginTop: '0.5rem' }}>
                <button type="button" onClick={() => setStep(5)} className="btn btn-ghost">← Back</button>
                <button type="button" onClick={() => setStep(7)} className="btn btn-primary">Continue →</button>
              </div>
            </div>
          )}

          {/* ── STEP 7: Documents & Declaration ── */}
          {step === 7 && (
            <form onSubmit={handleSubmit}>
              <h3 className="section-title">Documents to Attach</h3>
              <p className="section-subtitle">Upload certified copies of all required documents. PDF, JPG, PNG accepted. Max 5MB each.</p>

              <div className="alert alert-info" style={{ marginBottom: '1.5rem' }}>
                <div>
                  <strong>Required documents for Top-Up applicants:</strong>
                  <ul style={{ marginTop: '0.5rem', paddingLeft: '1.25rem', lineHeight: 1.8, fontSize: '0.875rem' }}>
                    <li>Certified true copies of certificates / results slips and birth certificate</li>
                    <li>Transcripts for those with tertiary certifications (HND, Diploma, etc.)</li>
                    <li>Any other relevant academic records</li>
                    <li>Two (2) recent passport-sized photographs (one affixed to form)</li>
                  </ul>
                </div>
              </div>

              <div className="form-group">
                <label>Passport Photograph * (JPG/PNG, max 2MB)</label>
                <input type="file" name="photo" onChange={handleFileChange} accept="image/*" required />
                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Recent photo, plain background</span>
              </div>
              <div className="form-group">
                <label>Certificates / Results Slips * (PDF or image, max 5MB)</label>
                <input type="file" name="certificates" onChange={handleFileChange} accept=".pdf,image/*" required />
                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Certified copies — HND, Diploma, WASSCE, etc.</span>
              </div>
              <div className="form-group">
                <label>Transcripts * (PDF, max 5MB)</label>
                <input type="file" name="transcripts" onChange={handleFileChange} accept=".pdf,image/*" required />
                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Official transcripts from your tertiary institution</span>
              </div>
              <div className="form-group">
                <label>Birth Certificate or National ID * (PDF or image, max 5MB)</label>
                <input type="file" name="birthCert" onChange={handleFileChange} accept=".pdf,image/*" required />
              </div>

              <hr className="divider" />
              <h3 className="section-title">Candidate Declaration</h3>
              <div style={{
                background: 'var(--surface-3)', border: '1px solid var(--border)',
                borderRadius: 'var(--radius-sm)', padding: '1.25rem',
                fontSize: '0.875rem', color: 'var(--text-secondary)', lineHeight: 1.7,
                marginBottom: '1.25rem',
              }}>
                I hereby declare that all the above information provided by me is true and correct, and that I could be
                denied admission, or be withdrawn from the University after admission, if the information on this form
                proves to be false.
              </div>

              <div className="form-grid" style={{ marginBottom: '1.5rem' }}>
                <div className="form-group" style={{ marginBottom: 0 }}>
                  <label>Full Name (as signature) *</label>
                  <input type="text" placeholder={`${personal.firstName} ${personal.surname}`.trim() || 'Your full name'} required />
                </div>
                <div className="form-group" style={{ marginBottom: 0 }}>
                  <label>Date *</label>
                  <input type="date" required defaultValue={new Date().toISOString().split('T')[0]} />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '0.75rem' }}>
                <button type="button" onClick={() => setStep(6)} className="btn btn-ghost">← Back</button>
                <button type="submit" className="btn btn-success btn-lg" disabled={loading}>
                  {loading ? 'Submitting Application...' : 'Submit Application'}
                </button>
              </div>
            </form>
          )}

        </div>
      </div>
    </div>
  );
};

export default ApplicationFormTopUp;
